/* Industrial Archive — design system tokens
 *
 * Dark-first. Monospace is the primary type voice; radius tokens are all zero
 * because shape is expressed with a cut corner, not a curve.
 */

:root {
  --color-paper: #0b0c0d;
  --color-ink: #e6e8e3;
  --color-graphite: #8d938c;
  --color-line: rgba(230, 232, 227, 0.16);
  --color-oxide: #d98b2b;
  --color-moss: #6f9f7c;

  --font-display: "JetBrains Mono", ui-monospace, monospace;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  /* Dense spacing scale: four steps, tightly packed. */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-5: 1.25rem;

  --radius-sm: 0px;
  --radius-md: 0px;
  --radius-lg: 0px;

  --motion-fast: 140ms;
  --motion-normal: 240ms;
  --motion-slow: 420ms;
  --motion-ease: cubic-bezier(0.4, 0, 0.2, 1);

  --cut: 10px;
  --grid-cell: 24px;
  --grid-module: 96px;
}

.light {
  --color-paper: #f2f2ef;
  --color-ink: #101112;
  --color-graphite: #5c5f5d;
  --color-line: rgba(16, 17, 18, 0.18);
  --color-oxide: #a8620f;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --motion-fast: 0ms;
    --motion-normal: 0ms;
    --motion-slow: 0ms;
  }
}
